//! `cargo xtask dev-keys [--out <dir>] [--force]`
//!
//! Dev KEK (base64 32 bytes), Ed25519 aur ES256 signing keys (PKCS#8 DER) generate karta hai:
//! - `<out>/keys/kek.b64`, `ed25519.pk8`, `ed25519.pub.b64`, `es256.pk8`, `es256.pub.b64`
//! - `<out>/keys.env`: sirf key env vars (`KEK_*`, `JWT_*`) + commented mysql placeholder.
//!
//! `<out>/dev.env` ko yeh command **kabhi nahi chhuta** (usmein local MySQL credentials rehte hain).
//! Dono env files saath load karo (`dev.env` + `keys.env`).
//!
//! Default `<out>` = `.dev` (gitignored). Existing generated files overwrite nahi hoti jab tak `--force` na ho.
//! Output sirf paths aur fingerprints; key bytes kabhi print nahi hote. Permissions: unix 0600/0700; Windows par
//! `icacls` (best effort). Directory permissions sirf unhi directories par badalte hain jo is run ne khud banayi;
//! pehle se maujood `--out` par kabhi `icacls /inheritance:r` nahi chalta.

use anyhow::{Context, Result, bail};
use base64::Engine as _;
use base64::engine::general_purpose::STANDARD;
use std::fs;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use zeroize::Zeroizing;

// `print_stdout` workspace mein deny hai; xtask ka human output stderr par jaata hai (`eprintln!`, allowed).
macro_rules! say {
    ($($arg:tt)*) => { eprintln!($($arg)*) };
}

pub fn run(args: impl Iterator<Item = String>) -> Result<()> {
    let mut out = PathBuf::from(".dev");
    let mut force = false;
    let mut args = args;
    while let Some(a) = args.next() {
        match a.as_str() {
            "--force" => force = true,
            "--out" => {
                out = PathBuf::from(args.next().context("--out needs a directory")?);
            }
            other => bail!("unknown argument `{other}`; usage: dev-keys [--out <dir>] [--force]"),
        }
    }
    generate(&out, force)
}

/// Generated files, in a fixed order: kek, ed pk8, ed pub, es pk8, es pub, keys.env.
fn targets(out: &Path) -> [PathBuf; 6] {
    let k = out.join("keys");
    [
        k.join("kek.b64"),
        k.join("ed25519.pk8"),
        k.join("ed25519.pub.b64"),
        k.join("es256.pk8"),
        k.join("es256.pub.b64"),
        out.join("keys.env"),
    ]
}

fn generate(out: &Path, force: bool) -> Result<()> {
    let keys_dir = out.join("keys");
    let files = targets(out);
    if !force {
        let existing: Vec<String> = files
            .iter()
            .filter(|p| p.exists())
            .map(|p| p.display().to_string())
            .collect();
        if !existing.is_empty() {
            bail!(
                "refusing to overwrite existing files (use --force): {}",
                existing.join(", ")
            );
        }
    }
    // Sirf wahi directories restrict hongi jo hum banate hain.
    let out_existed = out.exists();
    let keys_existed = keys_dir.exists();
    fs::create_dir_all(&keys_dir).with_context(|| format!("create {}", keys_dir.display()))?;
    if !keys_existed {
        restrict(&keys_dir);
    }
    if !out_existed {
        restrict(out);
    }

    let kek_id = crypto::devkeys::dev_kek_id()?;
    let kek_b64 = crypto::devkeys::generate_kek_b64()?;
    let ed = crypto::devkeys::generate_ed25519()?;
    let es = crypto::devkeys::generate_es256()?;

    write_secret(&files[0], kek_b64.as_bytes(), force)?;
    write_secret(&files[1], &ed.pkcs8, force)?;
    write_secret(&files[2], STANDARD.encode(&ed.public_key).as_bytes(), force)?;
    write_secret(&files[3], &es.pkcs8, force)?;
    write_secret(&files[4], STANDARD.encode(&es.public_key).as_bytes(), force)?;

    let env = Zeroizing::new(format!(
        "# Generated by `cargo xtask dev-keys`. DEV ONLY: staging/production startup refuses dev keys.\n\
         # Key material: gitignored, never share or commit. Load together with .dev/dev.env (DB settings live there).\n\
         # DATABASE_URL=mysql://USER:PASSWORD@127.0.0.1:3306/DBNAME   (placeholder; set in dev.env)\n\
         KEK_PROVIDER=env\n\
         KEK_ENV_ACTIVE_ID={kek_id}\n\
         KEK_ENV_{kek_id}={}\n\
         JWT_ISSUER=dsecure-dev\n\
         JWT_SIGNING_KID_MEMBER={}\n\
         JWT_SIGNING_KID_STAFF={}\n\
         # Signing keys (PKCS#8 DER) for dev seeding: {} and {}\n",
        *kek_b64,
        crypto::devkeys::dev_signing_kid("member"),
        crypto::devkeys::dev_signing_kid("staff"),
        files[1].display(),
        files[3].display(),
    ));
    write_secret(&files[5], env.as_bytes(), force)?;

    say!("dev keys written (no key bytes shown):");
    for f in &files {
        say!("  {}", f.display());
    }
    say!("existing dev.env left untouched (if any)");
    say!("KEK id         : {kek_id}");
    say!(
        "dev marker fp  : {}",
        crypto::devkeys::dev_marker_fingerprint()
    );
    say!(
        "ed25519 pub fp : {}",
        crypto::devkeys::fingerprint8(&ed.public_key)
    );
    say!(
        "es256 pub fp   : {}",
        crypto::devkeys::fingerprint8(&es.public_key)
    );
    Ok(())
}

fn write_secret(path: &Path, data: &[u8], force: bool) -> Result<()> {
    let mut opts = fs::OpenOptions::new();
    opts.write(true);
    if force {
        opts.create(true).truncate(true);
    } else {
        opts.create_new(true);
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        opts.mode(0o600);
    }
    let mut f = opts
        .open(path)
        .with_context(|| format!("open {}", path.display()))?;
    f.write_all(data)
        .with_context(|| format!("write {}", path.display()))?;
    drop(f);
    restrict(path);
    Ok(())
}

/// Best effort permission tightening; failure sirf warning (dev tool).
fn restrict(path: &Path) {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        let mode = if path.is_dir() { 0o700 } else { 0o600 };
        if fs::set_permissions(path, fs::Permissions::from_mode(mode)).is_err() {
            say!(
                "warning: could not restrict permissions on {}",
                path.display()
            );
        }
    }
    #[cfg(windows)]
    {
        let Some(user) = std::env::var_os("USERNAME") else {
            say!(
                "warning: USERNAME not set; permissions not restricted on {}",
                path.display()
            );
            return;
        };
        // Pehle current user ko explicit full access do (DOMAIN\user, warna ambiguous name resolve ho sakta hai),
        // tabhi inheritance hatao: ulta order karne par user khud lock ho sakta hai.
        let mut who = user.to_string_lossy().into_owned();
        if let Some(domain) = std::env::var_os("USERDOMAIN") {
            who = format!("{}\\{who}", domain.to_string_lossy());
        }
        let perm = if path.is_dir() { "(OI)(CI)F" } else { "F" };
        let icacls = |args: &[&str]| {
            std::process::Command::new("icacls")
                .arg(path)
                .args(args)
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .status()
                .is_ok_and(|s| s.success())
        };
        let ok = icacls(&["/grant:r", &format!("{who}:{perm}")]) && icacls(&["/inheritance:r"]);
        if !ok {
            say!(
                "warning: icacls failed; permissions not restricted on {}",
                path.display()
            );
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use common::config_util::Env;

    fn tmp(name: &str) -> PathBuf {
        let mut p = std::env::temp_dir();
        p.push(format!("dsecure-xtask-{name}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&p);
        p
    }

    #[test]
    fn generates_refuses_overwrite_and_force_works() {
        let dir = tmp("gen");
        generate(&dir, false).expect("first");
        let env = fs::read_to_string(dir.join("keys.env")).expect("env");
        assert!(env.contains("KEK_PROVIDER=env"));
        assert!(!env.contains("postgres"));
        assert!(env.contains("mysql://USER:PASSWORD@"));
        let kek = fs::read_to_string(dir.join("keys/kek.b64")).expect("kek");
        assert_eq!(STANDARD.decode(kek.trim()).expect("b64").len(), 32);
        assert!(crypto::is_dev_fingerprint(
            env.lines()
                .find(|l| l.starts_with("KEK_ENV_ACTIVE_ID="))
                .expect("id")
        ));
        let ed = fs::read(dir.join("keys/ed25519.pk8")).expect("ed");
        crypto::Ed25519Signer::from_pkcs8("k", &ed).expect("loadable");
        let es = fs::read(dir.join("keys/es256.pk8")).expect("es");
        crypto::Es256Signer::from_pkcs8("k", &es).expect("loadable");

        assert!(
            generate(&dir, false).is_err(),
            "must refuse without --force"
        );
        let before = fs::read(dir.join("keys/ed25519.pk8")).expect("before");
        assert_eq!(before, ed, "refused run must not modify files");
        generate(&dir, true).expect("force");
        assert_ne!(fs::read(dir.join("keys/ed25519.pk8")).expect("after"), ed);
        let _ = fs::remove_dir_all(&dir);
    }

    /// CR-3: maujood dev.env (local MySQL credentials) ko kabhi nahi chhuta, `--force` mein bhi nahi.
    #[test]
    fn existing_dev_env_is_never_touched() {
        let dir = tmp("devenv");
        fs::create_dir_all(&dir).expect("mkdir");
        let original = "DATABASE_URL=mysql://app:real-local-pw@127.0.0.1:3307/x\nLOCAL_MYSQL_ROOT_PASSWORD=pw\n";
        fs::write(dir.join("dev.env"), original).expect("write");
        generate(&dir, false).expect("generate");
        assert_eq!(
            fs::read_to_string(dir.join("dev.env")).expect("r"),
            original
        );
        generate(&dir, true).expect("force");
        assert_eq!(
            fs::read_to_string(dir.join("dev.env")).expect("r"),
            original
        );
        assert!(dir.join("keys.env").exists());
        let _ = fs::remove_dir_all(&dir);
    }

    /// CR-3: generated key vars + mysql URL = `AppConfig::load` (dev) accept karta hai, aur dev signing kid / KEK
    /// staging mein `DevKeyCheck` se reject hote hain.
    #[test]
    fn generated_key_vars_load_with_mysql_url_in_dev_and_are_refused_in_staging() {
        let dir = tmp("cfg");
        generate(&dir, false).expect("generate");
        let text = fs::read_to_string(dir.join("keys.env")).expect("env");
        let mut pairs: Vec<(String, String)> = text
            .lines()
            .filter(|l| !l.trim_start().starts_with('#') && l.contains('='))
            .filter_map(|l| l.split_once('='))
            .map(|(k, v)| (k.to_owned(), v.to_owned()))
            .collect();
        pairs.push(("DSECURE_ENV".into(), "dev".into()));
        pairs.push((
            "DATABASE_URL".into(),
            "mysql://app:pw@127.0.0.1:3307/dsecure_dev".into(),
        ));
        let env = Env::from_pairs(pairs.clone());
        config::AppConfig::load_with(&env, &[&crypto::DevKeyCheck]).expect("dev config accepts");

        for (k, v) in &mut pairs {
            if k == "DSECURE_ENV" {
                "staging".clone_into(v);
            }
        }
        let e = config::AppConfig::load_with(&Env::from_pairs(pairs), &[&crypto::DevKeyCheck])
            .expect_err("staging must refuse dev keys");
        assert!(e.has_key("KEK_ENV_ACTIVE_ID"));
        assert!(e.has_key("JWT_SIGNING_KID_MEMBER"));
        assert!(e.has_key("JWT_SIGNING_KID_STAFF"));
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn rejects_unknown_args() {
        assert!(run(["--bogus".to_owned()].into_iter()).is_err());
        assert!(run(["--out".to_owned()].into_iter()).is_err());
    }

    /// Windows: key files par sirf current user (Everyone/Users/Authenticated Users nahi).
    #[cfg(windows)]
    #[test]
    fn windows_key_files_are_restricted() {
        let dir = tmp("acl");
        generate(&dir, false).expect("generate");
        for f in targets(&dir) {
            let out = std::process::Command::new("icacls")
                .arg(&f)
                .output()
                .expect("icacls runs");
            let text = String::from_utf8_lossy(&out.stdout).to_lowercase();
            assert!(out.status.success(), "icacls failed for {}", f.display());
            for banned in ["everyone", "builtin\\users", "authenticated users"] {
                assert!(
                    !text.contains(banned),
                    "{} grants `{banned}`: {text}",
                    f.display()
                );
            }
        }
        let _ = fs::remove_dir_all(&dir);
    }

    /// L-3: pehle se maujood `--out` directory ki ACL nahi badalti (sirf apni files + apni banayi dirs).
    #[cfg(windows)]
    #[test]
    fn windows_existing_out_dir_acl_not_modified() {
        let dir = tmp("acl-existing");
        fs::create_dir_all(&dir).expect("mkdir");
        let acl = |p: &Path| {
            let o = std::process::Command::new("icacls")
                .arg(p)
                .output()
                .expect("icacls");
            String::from_utf8_lossy(&o.stdout)
                .replace(&p.display().to_string(), "")
                .trim()
                .to_owned()
        };
        let before = acl(&dir);
        generate(&dir, false).expect("generate");
        assert_eq!(acl(&dir), before, "existing --out dir ACL changed");
        let _ = fs::remove_dir_all(&dir);
    }
}
